            C++

    #include <iostream>
using namespace std;

string Kdigits(int n, int k)
{
    // Stores the resultant digits
    string res = "";

    // Initialize remainder
    int rem = 1;

    // Generate first k digits after decimal
    for (int i = 0; i < k; i++)
    {
        // Obtain next digit
        int digit = (10 * rem) / n;

        res += char(digit + '0');

        // Update remainder
        rem = (10 * rem) % n;
    }

    return res;
}

int main()
{
    int n = 50, k = 4;

    cout << Kdigits(n, k);

    return 0;
}


